import * as THREE from 'three/webgpu';
import { texture, uv, vec4, uniform, mix } from 'three/tsl';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'home-subhead';
  group.position.set(0, 1.85, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const geometry = new THREE.PlaneGeometry(2.4, 1.5);
  const material = new THREE.MeshBasicNodeMaterial({ transparent: true });

  const map = ctx.textureLoader.load('/prism-mock/home/nodes/cta-hero-isolated.png');
  map.colorSpace = THREE.SRGBColorSpace;

  const grainAmount = uniform(0.03);
  const uvNode = uv();
  const texColor = texture(map, uvNode);

  // simple procedural grain via uv-based noise-ish pattern (cheap sine pattern, static)
  const grain = uvNode.x.mul(37.13).sin().mul(uvNode.y.mul(91.7).sin()).mul(0.5).add(0.5);
  const grained = texColor.rgb.add(grain.sub(0.5).mul(grainAmount));

  material.colorNode = vec4(grained, texColor.a);

  const plane = new THREE.Mesh(geometry, material);
  plane.name = 'home-subhead-plane';
  group.add(plane);

  let textMesh = null;
  try {
    textMesh = createTextMesh({
      text: 'Atelier Noir — precise · luxury · technical',
      font: 'Lora',
      weight: 400,
      size: 0.2,
      color: '#e8ecf2',
      atlas: ctx.fontAtlas,
      maxWidth: 2.2,
      align: 'center',
    });
    textMesh.position.set(0, 0, 0.01);
    group.add(textMesh);
  } catch (e) {
    // fallback silently if font atlas unavailable
  }

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map) map.dispose();
    if (textMesh) {
      textMesh.geometry?.dispose?.();
      textMesh.material?.dispose?.();
    }
  };

  return group;
}
